def min_buses(a, b, roads, bus_routes):
    graph = defaultdict(list)
    time = defaultdict(int)

    for i in range(1, len(roads) + 1):
        graph[(roads[i - 1][0], i)] = [(roads[i - 1][1], i)]
        graph[(i, roads[i - 1][1])] = [(a, roads[i - 1][0])]

    for route in bus_routes:
        x, y = route
        if len(graph[(x, y)]) == 0:
            return -1
        if len(graph[(y, x)]) == 0:
            continue
        time[(x, y, y)] = time[(y, x, x)] = 0
        queue = list(graph[(x, y)])
        while queue:
            position, bus = queue.pop(0)
            for nxt in graph[(position, bus)]:
                if time[nxt[0], position, nxt[0], nxt[1], time[(position, bus), x, y]] == 0:
                    time[(position, bus), x, y] = time[(x, y, y), x, nxt[1], nxt[0]]
                    queue.append((nxt[0], nxt[1]))

    if time[(b, a, b), b, b] == 0:
        return -1
    elif time[(b, a, b), b, b] >= float('inf'):
        return 1
    else:
        return time[(b, a, b), b, b] + 1

