def max_power_plant_output(n: int, m: int, gen_data: List[Tuple[int, int, int]]) -> int:
    generators: List[List[int]] = [[] for _ in range(n)]
    for coefficients, lower, upper, *_, output in sorted(gen_data, key=lambda x: x[0], reverse=True):
        for i in range(len(generators)):
            if lower <= i <= upper:
                generators[i] += [coefficients, lower, upper]

    max_output: int = 0
    solution: List[int] = list(range(n))
    for i in range(n - 1, -1, -1):
        for j in range(min(generators[i]), max(generators[i]) + 1):
            if solution[i] != j:
                output = sum(coeff*(j**2) + val for _, val, _, coeff in generators[i])
                if output > max_output:
                    max_output, solution = output, list([j] + (solution[:i] + solution[i+1:]))  
    return max_output

