def find_connected_component(n, k, i, j, grid):
    stack = [(i, j)]
    visited = set()
    size = 0
    while stack:
        x, y = stack.pop()
        visited.add((x, y))
        size += 1
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == '.' and (nx, ny) not in visited:
                stack.append((nx, ny))
    X = N = size
    if i >= k and i < n - k:
        if j >= k and j < n - k and ((i - k + 1, j - k + 1) not in visited) and ((i + k - 1, j + k - 1) not in visited):
            for dx, dy in [(-1, -1), (1, 1), (-1, 1), (1, -1)]:
                nx, ny = i - k + dx, j - k + dy
                if 0 <= nx < n - k + 1 and 0 <= ny < n - k + 1 and grid[nx][ny] == '.' and (nx, ny) not in visited:
                    if ((nx + k + 1, ny + k + 1) not in visited and grid[nx + k + 1][ny + k + 1] == '.') or (
                            (nx - k - 1, ny - k - 1) not in visited and grid[nx - k - 1][ny - k - 1] == '.'):
                        X, N = find_connected_component(n, k, nx + 1, ny + 1, grid), size
                    else:
                        X, N = find_connected_component(n, k, nx + 1, ny + 1, grid), size
    return max(X, N)

