def find_answer(n, pairs):
    results = [0] * (1 << (n-1))
    for seed in product([0, 1], repeat=n-1):
        permutation = [e[n-1] for e in seed]
        valid = True
        for i in range(n-1):
            if pairs[permutation[i]][int(bin(seed[i])[2:][::-1], 2)] != int(bin(seed[i+1])[2:][::-1], 2):
                valid = False
                break
        if valid:
            for s in range(len(results)):
                binary_string = bin(s)[2:].zfill(n-1)
                if all(binary_string[i] == str(seed[i]) for i in range(n-1)):
                    results[s] += 1
    return results

