def max_bitwise_xor_length(n, s):
    MOD = 10**9 + 7
    suffix_xor = [0]
    max_xor = 0

    for i in range(n - 1, -1, -1):
        if s[i] == '1':
            suffix_xor.append(1)
        else:
            suffix_xor.append(0)

    lhs_xor = [0]
    lhs_count = 0
    for i in range(n + 1):
        if s[i] == '1':
            lhs_count += 1
        lhs_xor.append(lhs_count)

    for i in range(n + 1):
        odd = suffix_xor[i] - 1
        even = suffix_xor[n - i + 1]
        if odd >= 0:
            odd += lhs_xor[n - i % 2]
        if even >= 0:
            even += lhs_xor[i % 2]
        max_xor = max(max_xor, odd + even)

    return max_xor % MOD

