def calculate_odd_points(n, y):
    odd_points = [False] * n
    odd_points[0] = False
    odd_points[1] = False

    i = 3
    while i * i <= n:
        if n % i == 0:
            j = i
            while j * i <= n:
                odd_points[j * i - 1] = False
                j += 2
        i += 2
    for i in range(2, n + 1):
        if not odd_points[i - 1]:
            odd_points[i] = True
    return sum(odd_points)

def calculate_correct_triplets(num_nodes, prime_y) -> int:
    odd_count = calculate_odd_points(num_nodes, prime_y)
    y = prime_y
    odd_count_diff = odd_count // y
    if odd_count != 0:
        odd_count_diff = odd_count_diff - (odd_count - odd_count_diff)
    return (y - 1) * (odd_count_diff * (odd_count_diff + 1) + y * odd_count - odd_count_diff * odd_count_diff)

