def calculate_max_output(generator_data, limits, restrictions):
    n, m = len(generator_data), len(restrictions)

    # Calculate the maximum output for each generator
    max_output = [sum(d * i**2 for i, (_, _) in enumerate(generator_data)) for d in generator_data]

