    def check_bounds(x):
        for u, v, d in restrictions:
            if x[u-1] + d <= x:
                while x[u-1] + d <= x[u]:
                    if x[u-1] + d < limits[v-1]:
                        return False
                    x[u-1] += d
                break
            if x[u-1] <= x:
                while x[u-1] <= x[0]:
                    x[u-1] += d
                break
        for v in range(1, n):
            if x - limits[v-1] < 0 or x[v-1] - limits[v-1] < 0:
                return False
        return True

    x = [d / 2 for d in generator_data]  # Initial guess can be any positive number
    for _ in range(10):  # Try to refine x a few times iteratively
        x_new = (tensor_min(x, *[tensor_min(x, check_bounds) for _ in range(n)]) for _ in range(n))
        if all(u == 0 for u in x_new):
            break
        x = x_new

    return sum(d * x[i]**2 for i, d in enumerate(max_output))

