            if grid[i][j] == '.':
                start = (i, j)
                visited = set()
                while start in connected_components:
                    connected_components.add(start)
                    visited.add(start)
                    neighbors = []
                    if start[0] > 0 and grid[start[0] - 1][start[1]] == '.':
                        neighbors.append((start[0] - 1, start[1]))
                    if start[1] > 0 and grid[start[0]][start[1] - 1] == '.':
                        neighbors.append((start[0], start[1] - 1))
                    if start[0] < n - 1 and grid[start[0] + 1][start[1]] == '.':
                        neighbors.append((start[0] + 1, start[1]))
