                        neighbors.append((start[0], start[1] + 1))
                    new_start = neighbors[0]
                    for neighbor in neighbors[1:]:
                        if new_start not in connected_components:
                            connected_components.add(neighbor)
                            visited.add(neighbor)
                            start = neighbor
                            break
    return max(len(component) for component in connected_components)

