def largest_connected_component(n, k, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False] * n for _ in range(n)]
    directions = set([(r, c) for r in range(n) for c in range(n) if grid[r][c] == "." and not visited[r][c]])

    def dfs(r, c):
        visited[r][c] = True
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc] and grid[nr][nc] == ".":
                dfs(nr, nc)

    connected_cells = [0] * (k * k)
    for r in range(n):
        for c in range(n):
            if grid[r][c] == ".":
                dfs(r, c)
                for nr, nc in directions:
                    if not visited[r + nr][c + nc]:
                        for i in range(k):
                            for j in range(k):
                                connected_cells[i + k * j] = max(connected_cells[i + k * j], abs(r + i) + ((r - abs(i)) // k))

    return max(connected_cells)
