def max_xor_sums(N, S):
    masks = {2**i - 1 for i in range(1, N+1)}
    results = []
    for bit in range(30):
        max_xor = 0
        for mask in masks:
            for i in range(1, N+1-mask.bit_length()-1):
                l = (i - (2**bit - 1)) % (N+1)
                r = (i + (2**bit - 1)) % (N+1)
                xor_val = eval_S(xor_helper(S[l:r], S[l:r]))
                max_xor = max(max_xor, xor_val)
        results.append(max_xor)
