def largest_connected_component(grid, k):
    n = len(grid)
    connected_components = []

    def dfs(row, col):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == '.':
                grid[nr][nc] = '*'
                dfs(nr, nc)

    for r in range(n):
        for c in range(n):
            if grid[r][c] == '.':
                dfs(r, c)
                connected_components.append((r, c, 'DFS', len(grid[r][c:])))

    max_size = 0
    for row, col, _, blocked_size in connected_components:
        for m in range(1, k):
            max_size = max(max_size, blocked_size + m // 2)
    return max_size

