import sys

def count_triplets(n, y, k, x):
    y_count = [0] * (y // 2 + 1)
    x_count = [0] * (y // 2 + 1)

    for i in range(1, n + 1):
        if pow(k, x, y) > pow(k, y // 2 + 1, y):
            return 0
        x_count[pow(k, x, y) % y] += 1
        x, y = y // 2 + 1, y % y
        if x % 2:
            y_count[(x // 2 + 1) % y] += 1

    res = 0
    for i in range(x * y // 2 + 1, y // 2 + 1):
        for ii in range(i, x * y // 2 + 1):
            if x_count[ii] > y_count[i - ii]:
                res += y_count[i - ii] * x_count[ii]
            if x_count[ii] == y_count[i - ii]:
                res += (ii - 2 * y_count[i - ii]) * (x_count[ii] + 1 - y_count[i - ii]) // 2
    return res

