def max_connected_component(n, k, grid):
    max_size = 0
    rows = [0] * n
   cols = [0] * n
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'X':
                continue
            empty_neighbors = 0
            for ni, nj in ((i-1, j), (i+1, j), (i, j-1), (i, j+1)):
                if 0 <= ni < n and 0 <= nj < n and grid[ni][nj] == 'X':
                    empty_neighbors += 1
            rows[i] += empty_neighbors
            cols[j] += empty_neighbors
            if empty_neighbors >= k:
                if empty_neighbors == k:
                    current_size = k + 1
                else: 
                    current_size = empty_neighbors + 1
                max_size = max(max_size, current_size)
            else:
                max_size = max(max_size, k)
                break

    return max_size
