def count_polynomials(a): 
    dp = [0] * max(a)  # Max value of coefficients considering limit
    for x in a:  
        dp[x%MOD] += 1
        for i in range(x%MOD, -1, -1):  
            if i > 0: 
                dp[i%MOD] +=  dp[(i+1-x)%MOD] 
    return (-(MOD - 2)*max(dp)%MOD + 10**9)%MOD

